  /**
   * The SHA of the merge commit
   */
  "merge_commit_sha"?: string;
  /**
   * Whether the pull request can be merged
   */
  "mergeable"?: boolean;
  /**
   * Whether the pull request has been merged
   */
  "merged"?: boolean;
  "merged_at"?: string;
  "merged_by"?: User;
  "milestone"?: Milestone;
